class Solution:
    def checkPrimeFrequency(self, nums):
        from collections import Counter
        def is_prime(f):
            if f < 2: return False
            i = 2
            while i * i <= f:
                if f % i == 0: return False
                i += 1
            return True
        return any(is_prime(f) for f in Counter(nums).values())

c.cpp:
class Solution {
public:
    bool checkPrimeFrequency(vector<int>& nums) {
        unordered_map<int,int> cnt;
        for (int x : nums) cnt[x]++;
        auto isPrime = [](int f) {
            if (f < 2) return false;
            for (int i = 2; i * i <= f; i++) if (f % i == 0) return false;
            return true;
        };
        for (auto& [v, f] : cnt) if (isPrime(f)) return true;
        return false;
    }
};

