class Solution {
    public boolean checkPrimeFrequency(int[] nums) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int x : nums) cnt.merge(x, 1, Integer::sum);
        for (int f : cnt.values()) {
            if (f < 2) continue;
            boolean p = true;
            for (int i = 2; i * i <= f; i++) if (f % i == 0) { p = false; break; }
            if (p) return true;
        }
        return false;
    }
}

